INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Ngày phong tỏa tiền trên tài khoản liên kết', 'vi', 'Ngày phát sinh hoặc ghi nhận khoản phong tỏa trên tài khoản liên kết', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:07:13.659000000+00:00', now()), coalesce('2026-09-15T16:07:13.659000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Phí lưu ký', 'vi', 'Chi phí định kỳ để duy trì lưu giữ, quản lý tập trung cổ phiếu/trái phiếu/chứng chỉ quỹ trong tài khoản. Do VSDC quy định, công ty chứng khoán thu hộ; thu hàng tháng dù tài khoản có phát sinh mua bán hay không', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T10:59:07.073000000+00:00', now()), coalesce('2026-09-15T10:59:07.073000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Phí ứng dự kiến', 'vi', 'Phần phí phải trả nếu ứng trước tiền bán; không phát sinh nếu không ứng. Mức phí trong nội dung nguồn là 0,042% cho mỗi ngày ứng trước.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:02:26.633000000+00:00', now()), coalesce('2026-09-15T16:02:26.633000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Số tiền phong tỏa trên tài khoản liên kết', 'vi', 'Số tiền đang bị phong tỏa trên tài khoản ngân hàng hoặc iPower liên kết; khoản tiền này tạm thời chưa thể chuyển hoặc rút tự do vì đang liên quan đến giao dịch hay thao tác trên TCBS.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:06:17.966000000+00:00', now()), coalesce('2026-09-15T16:06:17.966000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Số tiền được giải tỏa', 'vi', 'Phần tiền đã được mở phong tỏa và không còn nằm trong khoản phong tỏa tương ứng.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:06:34.853000000+00:00', now()), coalesce('2026-09-15T16:06:34.853000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền bán chờ về', 'vi', 'Tiền từ giao dịch bán chứng khoán đã khớp nhưng chưa đến ngày thanh toán về tài khoản. Theo quy định chứng khoán, tiền bán cổ phiếu về sau 2 ngày giao dịch (lệnh bán cổ phiếu vào ngày T thì sáng ngày T+2 không kể ngày nghỉ cuối tuần, nghỉ lễ mới về trên TKCK). Khoản này có thể hiển thị nhưng chưa thuộc tiền được rút.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:00:16.510000000+00:00', now()), coalesce('2026-09-15T16:00:16.510000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền có thể rút', 'vi', 'Tiền từ giao dịch bán chứng khoán đã khớp nhưng chưa đến ngày thanh toán về tài khoản. Theo quy định chứng khoán, tiền bán cổ phiếu về sau 2 ngày giao dịch (lệnh bán cổ phiếu vào ngày T thì sáng ngày T+2 không kể ngày nghỉ cuối tuần, nghỉ lễ mới về trên TKCK). Khoản này có thể hiển thị nhưng chưa thuộc tiền được rút.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T15:59:57.706000000+00:00', now()), coalesce('2026-09-15T15:59:57.706000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền có thể ứng', 'vi', 'Phần tiền bán chờ về mà hệ thống cho phép ứng trước. Khách hàng có thể chủ động kiểm tra ngày tiền bán về trong tính năng "Ứng trước tiền bán" trên ứng dụng TCInvest', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:01:18.985000000+00:00', now()), coalesce('2026-09-15T16:01:18.985000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền cổ tức chờ về', 'vi', 'Khoản cổ tức bằng tiền đang chờ hạch toán. Khoản này chỉ được rút khi được chuyển về Tiền mặt sau khoảng 1–3 tháng kể từ ngày nhận thông báo chia cổ tức từ tổ chức phát hành (tra cứu trên website vsd.vn theo mã chứng khoán).', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:03:01.351000000+00:00', now()), coalesce('2026-09-15T16:03:01.351000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền mua chờ khớp', 'vi', 'Tiền đang được dành cho các lệnh mua còn hiệu lực. Khi lệnh hoàn tất, bị hủy hoặc hết hiệu lực, phần tiền không sử dụng được cập nhật theo trạng thái lệnh.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:04:30.906000000+00:00', now()), coalesce('2026-09-15T16:04:30.906000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền mặt', 'vi', 'Số tiền đang có trên tài khoản TCBS sau khi trừ phần đã sử dụng trong ngày. Không bao gồm các khoản chỉ đang chờ về như tiền bán, cổ tức, trái tức hoặc lợi tức quỹ. Giá trị có thể âm khi phát sinh lệnh mua từ tiền bán chờ về, giải ngân ký quỹ hoặc tiền phong tỏa trên tài khoản liên kết.', 'Cash = Available_balance - Expected_cash_advance_margin_disbursement - Expected_deduction_from_linked_account', 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T15:55:06.531000000+00:00', now()), coalesce('2026-09-15T15:55:06.531000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền phong tỏa IA - phong tỏa khác', 'vi', 'Số dư trên tài khoản ngân hàng liên kết hoặc tài khoản iPower đang bị phong tỏa cho nghĩa vụ, gồm tiền cho lệnh mua khớp trong ngày hoặc tiền trả nợ ký quỹ theo các điều kiện được mô tả trong file nguồn.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:05:09.244000000+00:00', now()), coalesce('2026-09-15T16:05:09.244000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền phong tỏa cho nợ ký quỹ', 'vi', 'Số tiền được phong tỏa cho nghĩa vụ nợ ký quỹ trên tài khoản chứng khoán', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:05:54.479000000+00:00', now()), coalesce('2026-09-15T16:05:54.479000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền phong tỏa cho phí lưu ký', 'vi', 'Khoản tiền được phong tỏa để thanh toán phí lưu ký phát sinh khi sở hữu chứng khoán niêm yết/lưu ký; phí được thanh toán một lần vào cuối mỗi tháng.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:05:39.383000000+00:00', now()), coalesce('2026-09-15T16:05:39.383000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền trái tức chờ về', 'vi', 'Khoản lãi định kỳ (coupon) do tổ chức phát hành trái phiếu trả cho nhà đầu tư, thường theo chu kỳ hằng năm hoặc 6 tháng/lần tùy lịch đã thông báo.', NULL, 'published', 1, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T16:03:24.698000000+00:00', now()), coalesce('2026-09-15T16:03:24.698000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiền đã ứng', 'vi', 'Số tiền đã ứng được chuyển đổi thành Tiền mặt; có thể dùng để rút ra tài khoản ngân hàng hoặc thanh toán nghĩa vụ như tiền khớp mua chứng khoán, nợ ký quỹ và các khoản phí.
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tiểu khoản', 'vi', 'Tiểu khoản được chọn để tra cứu tiền trên TCBS, gồm Thường, Ký quỹ, Tài khoản người thân hoặc Tất cả.', NULL, 'published', 2, 'admin@corp.com', NULL, coalesce('2026-09-15T11:02:48.532000000+00:00', now()), coalesce('2026-09-15T11:02:48.532000000+00:00', now()));
INSERT INTO entities (id, kind, name, name_lang, definition, formula, status, version, created_by, category_id, created_at, updated_at) VALUES (gen_random_uuid(), 'Term', 'Tổng tiền', 'vi', 'Tổng các khoản tiền đang được ghi nhận trên tài khoản chứng khoán, bao gồm cả số dư trên tài khoản ngân hàng liên kết nếu khách hàng đang bật tính năng này', 'Tổng tiền = Tiền mặt + Tiền có thể ứng + Tiền mua chờ khớp + Tiền phong tỏa IA - phong tỏa khác + Tiền cổ tức chờ về + Tiền trái tức chờ về + Tiền lợi tức quỹ chờ về', 'published', 3, 'admin@corp.com', (SELECT id FROM categories WHERE name = 'Cash_WS'), coalesce('2026-09-15T11:05:29.523000000+00:00', now()), coalesce('2026-09-15T11:05:29.523000000+00:00', now()));
